    Bug 2061642 - Add the missing space between the two sentences in the calendar conflict dialog. r=mkmelin

    The second sentence was appended directly to the first, so the dialog read
    "changed on the server.Submitting your changes will overwrite ...".

    Joining the two sentences in JS fixes the separator for every locale. In ja
    and zh-CN both end with an ideographic full stop, which already carries the
    spacing, so the added space is superfluous there. Giving each sentence its
    own element would leave the separator to the locale, but that is more than
    this bug is about.

    Differential Revision: https://phabricator.services.mozilla.com/D318686

diff --git a/calendar/base/content/dialogs/calendar-conflicts-dialog.js b/calendar/base/content/dialogs/calendar-conflicts-dialog.js
index 793f123d803..81be00460e0 100644
--- a/calendar/base/content/dialogs/calendar-conflicts-dialog.js
+++ b/calendar/base/content/dialogs/calendar-conflicts-dialog.js
@@ -23,10 +23,10 @@ function onLoad() {
   descr.textContent = lazy.l10n.formatValueSync("item-modified-on-server");

   if (window.arguments[0].mode == "modify") {
-    descr.textContent += lazy.l10n.formatValueSync("modify-will-lose-data");
+    descr.textContent += " " + lazy.l10n.formatValueSync("modify-will-lose-data");
     document.l10n.setAttributes(dialog.getButton("accept"), "proceed-modify");
   } else {
-    descr.textContent += lazy.l10n.formatValueSync("delete-will-lose-data");
+    descr.textContent += " " + lazy.l10n.formatValueSync("delete-will-lose-data");
     document.l10n.setAttributes(dialog.getButton("accept"), "proceed-delete");
   }
 }
